import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        int namesakeCount = Namesakes.countBefore(owner, ownerRepository);
        int membershipLevel = MembershipLevel.of(owner, namesakeCount);
        dto.setNamesakeCount(namesakeCount);
        dto.setMembershipLevel(membershipLevel);
        dto.setBulkSignupWarning(BulkSignup.isWarned(owner, ownerRepository));
        Integer possibleDuplicateOf = PossibleDuplicate.of(owner, ownerRepository);
        dto.setPossibleDuplicate(possibleDuplicateOf != null);
        dto.setPossibleDuplicateOf(possibleDuplicateOf);
        LoggerFactory.getLogger("AUDIT").info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), membershipLevel);
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
==== Namesakes ====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Counts the owners that already existed before {@code owner} (created earlier, hence a
 * lower id) sharing its first and last name, compared case-insensitively. This is the
 * owner's namesake count at the moment it was created.
 */
public final class Namesakes {

    private Namesakes() {
    }

    public static int countBefore(Owner owner, OwnerRepository ownerRepository) {
        Integer id = owner.getId();
        if (id == null) {
            return 0;
        }
        return (int) ownerRepository.findAll().stream()
                .filter(other -> other.getId() != null && other.getId() < id)
                .filter(other -> other.getLastName().equalsIgnoreCase(owner.getLastName()))
                .filter(other -> other.getFirstName().equalsIgnoreCase(owner.getFirstName()))
                .count();
    }
}
==== IdentityKey ====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's identity key — the single value all duplicate detection is based on.
 * It is the normalized telephone, the email (already lower-cased, empty when absent) and the
 * {@link HouseholdId}, joined by '|'. Two owners are duplicates only when their whole keys
 * match; a shared telephone, email or household alone is not enough.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String email = owner.getEmail() == null ? "" : owner.getEmail();
        return telephone + "|" + email + "|" + HouseholdId.of(owner);
    }
}
==== EnsureOwnerIdentityUnique ====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Rejects a create when another owner shares this owner's whole {@link IdentityKey}.
 * This is the single consolidated duplicate check: a shared telephone, email or household
 * on its own is allowed — only an exact full-key match is a conflict.
 */
public class EnsureOwnerIdentityUnique {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = IdentityKey.of(owner);
        boolean taken = ownerRepository.findAll().stream()
                .anyMatch(other -> identityKey.equals(IdentityKey.of(other)));
        if (taken) {
            throw new DuplicateIdentityException("An owner with the same identity already exists");
        }
    }
}

==== DuplicateHouseholdException ====
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown by {@code EnsureOwnerHouseholdUnique} when a create request's last name and
 * address already belong to another owner. Handled by
 * {@link DuplicateHouseholdExceptionHandler}, which responds 409.
 */
public class DuplicateHouseholdException extends Exception {

    public DuplicateHouseholdException(String message) {
        super(message);
    }
}
==== DuplicateHouseholdExceptionHandler ====
package org.springframework.samples.petclinic.rest.escalation;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;

public class DuplicateHouseholdExceptionHandler {

    public void handle(@Parameter DuplicateHouseholdException ex,
            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.CONFLICT, ex.getMessage());
        response.send(ResponseEntity.status(HttpStatus.CONFLICT).body(detail));
    }
}
